#include <bits/stdc++.h>
#define fi first
#define se second
#define pb push_back
#define all(x) x.begin(), x.end()
#define rall(x) x.rbegin(), x.rend()
#define loop(i, a, b) for(int i = a; i < b; i++)
#define loopBack(i, a, b) for(int i = a; i >= b; i--)
#define INF INT_MAX
#define LINF LLONG_MAX
#define DINF DBL_MAX
#define MAX 150
using namespace std;
typedef long long ll;
typedef pair<int, int> ii;

struct FlowEdge {
    int v, u;
    ll cap, flow;
    FlowEdge(int v, int u, ll cap) : v(v), u(u), cap(cap), flow(0) {}
};

struct MaxFlowSolver {
    vector<FlowEdge> edges;
    vector<vector<int>> adj;
    vector<int> level, ptr;
    int n, s, t, edgeCount = 0;
    const ll INF_FLOW = 1e18;
    queue<int> q;

    MaxFlowSolver(int n, int s, int t) : n(n), s(s), t(t) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void addEdge(int v, int u, ll cap) {
        edges.emplace_back(v, u, cap);
        edges.emplace_back(u, v, 0);
        adj[v].push_back(edgeCount++);
        adj[u].push_back(edgeCount++);
    }

    bool buildLayerGraph() {
        fill(all(level), -1);
        level[s] = 0;
        q = queue<int>();
        q.push(s);
        while(!q.empty()) {
            int v = q.front(); q.pop();
            for(auto e_idx : adj[v]) {
                auto &e = edges[e_idx];
                if(e.cap - e.flow < 1) continue;
                if(level[e.u] != -1) continue;
                level[e.u] = level[v] + 1;
                q.push(e.u);
            }
        }
        return level[t] != -1;
    }

    ll sendFlow(int v, ll flow_in) {
        if(flow_in == 0) return 0;
        if(v == t) return flow_in;
        for(int &i = ptr[v]; i < (int)adj[v].size(); i++) {
            int e_idx = adj[v][i];
            auto &e = edges[e_idx];
            if(level[v] + 1 != level[e.u] || e.cap - e.flow < 1) continue;
            ll pushed = sendFlow(e.u, min(flow_in, e.cap - e.flow));
            if(pushed == 0) continue;
            e.flow += pushed;
            edges[e_idx ^ 1].flow -= pushed;
            return pushed;
        }
        return 0;
    }

    ll maxFlow() {
        ll totalFlow = 0;
        while(buildLayerGraph()) {
            fill(all(ptr), 0);
            while(ll pushed = sendFlow(s, INF_FLOW))
                totalFlow += pushed;
        }
        return totalFlow;
    }
};

int pos[MAX][MAX], matTempo[MAX][MAX], matAlc[MAX][MAX];

vector<ii> getNeighbors(int i, int j, vector<string> mat, int n) {
    vector<ii> neighbors;
    if(i + 1 < n) neighbors.pb({i+1, j});
    if(i - 1 >= 0) neighbors.pb({i-1, j});
    if(j + 1 < n) neighbors.pb({i, j+1});
    if(j - 1 >= 0) neighbors.pb({i, j-1});
    return neighbors;
}

void computeTemps(int i, int j, vector<string> sc, int n, int t) {
    if(i >= n || i < 0 || j >= n || j < 0 || (!isdigit(sc[i][j]) && sc[i][j] != 'Z') || (matTempo[i][j] != -1 && matTempo[i][j] <= t))
        return;
    if(matTempo[i][j] == -1)
        matTempo[i][j] = t;
    else
        matTempo[i][j] = min(t, matTempo[i][j]);
    computeTemps(i+1, j, sc, n, t+1);
    computeTemps(i-1, j, sc, n, t+1);
    computeTemps(i, j+1, sc, n, t+1);
    computeTemps(i, j-1, sc, n, t+1);
}

void computeAlcValues(int i, int j, vector<string> sc, int n, int t) {
    if(i >= n || i < 0 || j >= n || j < 0 || (matAlc[i][j] != -1 && matAlc[i][j] <= t) || !isdigit(sc[i][j]))
        return;
    if(matAlc[i][j] == -1)
        matAlc[i][j] = t;
    else
        matAlc[i][j] = min(t, matAlc[i][j]);
    computeAlcValues(i+1, j, sc, n, t+1);
    computeAlcValues(i-1, j, sc, n, t+1);
    computeAlcValues(i, j+1, sc, n, t+1);
    computeAlcValues(i, j-1, sc, n, t+1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t, n2, nMax, iZ, jZ;
    cin >> n >> t;
    n2 = n * n;
    nMax = n2 * 2;
    MaxFlowSolver flowSolver(nMax + 2, 0, nMax + 1);
    vector<string> sc(n), caps(n);
    int cnt = 1;
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            pos[i][j] = cnt++;
        }
    }
    for(int i = 0; i < n; i++) {
        cin >> sc[i];
        for(int j = 0; j < n; j++) {
            if(sc[i][j] == 'Z') {
                iZ = i; jZ = j;
            }
        }
    }
    for(int i = 0; i < n; i++) cin >> caps[i];

    memset(matTempo, -1, sizeof(matTempo));
    computeTemps(iZ, jZ, sc, n, 0);
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(matTempo[i][j] == -1 && isdigit(sc[i][j]))
                matTempo[i][j] = t;
        }
    }

    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            memset(matAlc, -1, sizeof(matAlc));
            if(isdigit(sc[i][j])) {
                int limit = sc[i][j] - '0';
                flowSolver.addEdge(0, pos[i][j], limit);
                computeAlcValues(i, j, sc, n, 0);
                for(int k = 0; k < n; k++) {
                    for(int l = 0; l < n; l++) {
                        if(matAlc[k][l] != -1 && matTempo[k][l] != -1 && matAlc[k][l] <= matTempo[k][l] && matAlc[k][l] <= t) {
                            bool crt = true;
                            if(matAlc[k][l] == matTempo[k][l]) {
                                crt = false;
                                if(k+1 < n && matAlc[k+1][l] != -1 && matAlc[k+1][l] < matTempo[k+1][l]) crt = true;
                                if(k-1 >= 0 && matAlc[k-1][l] != -1 && matAlc[k-1][l] < matTempo[k-1][l]) crt = true;
                                if(l+1 < n && matAlc[k][l+1] != -1 && matAlc[k][l+1] < matTempo[k][l+1]) crt = true;
                                if(l-1 >= 0 && matAlc[k][l-1] != -1 && matAlc[k][l-1] < matTempo[k][l-1]) crt = true;
                            }
                            if(crt) {
                                flowSolver.addEdge(pos[i][j], n2 + pos[k][l], limit);
                            }
                        }
                    }
                }
            }
        }
    }
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(isdigit(caps[i][j])) {
                flowSolver.addEdge(n2 + pos[i][j], nMax + 1, caps[i][j] - '0');
            }
        }
    }
    cout << flowSolver.computeMaxFlow() << '\n';
}
